using MediatR;using OAS.Application.Abstractions.Persistence;using OAS.Application.Abstractions.Persistence.Specifications;using OAS.Contracts.Accounting.ExchangeRates;using OAS.Contracts.Common.Pagination;using OAS.Domain.Accounting.Entities;using ContractRateType=OAS.Contracts.Accounting.Enums.ExchangeRateType;
namespace OAS.Application.Accounting.ExchangeRates.Queries.GetExchangeRates;
public sealed class GetExchangeRatesQueryHandler(IReadRepository<ExchangeRate,Guid> repository,IReadRepository<Currency,Guid> currencies):IRequestHandler<GetExchangeRatesQuery,PagedResult<ExchangeRateDto>>
{
 public async Task<PagedResult<ExchangeRateDto>> Handle(GetExchangeRatesQuery r,CancellationToken ct){var p=r.Request.Normalize();var s=new Specification<ExchangeRate>();if(!string.IsNullOrWhiteSpace(p.Search)){var term=p.Search.Trim();var currencyList=await currencies.ListAsync(new Specification<Currency>().Where(x=>x.Code.Contains(term)||x.NameAr.Contains(term)).ApplyPaging(0,200),ct);var ids=currencyList.Select(x=>x.Id).ToArray();s.Where(x=>ids.Contains(x.CurrencyId));}s.AddSort(nameof(ExchangeRate.RateDate),p.SortDirection).ApplyPaging((p.PageNumber-1)*p.PageSize,p.PageSize);var page=await repository.GetPageAsync(s,ct);var currencyIds=page.Items.Select(x=>x.CurrencyId).Distinct().ToArray();var map=(await currencies.ListAsync(new Specification<Currency>().Where(x=>currencyIds.Contains(x.Id)),ct)).ToDictionary(x=>x.Id);var items=page.Items.Select(e=>new ExchangeRateDto(e.Id,e.CurrencyId,map.TryGetValue(e.CurrencyId,out var c)?c.Code:string.Empty,e.RateDate,e.Rate,(ContractRateType)(byte)e.RateType,e.IsActive,Convert.ToBase64String(e.RowVersion))).ToArray();return new(){Items=items,PageNumber=p.PageNumber,PageSize=p.PageSize,TotalCount=page.TotalCount};}
}
